import React, { useState } from 'react';
import { useAuth } from '../auth/AuthContext';
import { mockEquipments } from '../data/mockEquipments';
import EquipmentCard from '../components/EquipmentCard';
import AuthModal from '../components/AuthModal';

export default function Home() {
  const { user } = useAuth();
  const [isModalOpen, setIsModalOpen] = useState(false);

  const handleBorrow = (equipment) => {
    if (user.role === 'guest') {
      setIsModalOpen(true);
    } else {
      alert(`ทำรายการยืม ${equipment.name} เรียบร้อยแล้ว!`);
    }
  };

  return (
    <div style={{ maxWidth: '1200px', margin: '0 auto', padding: '40px 20px' }}>
      <h2 style={{ fontSize: '24px', color: '#1E293B', marginBottom: '24px', fontWeight: '700' }}>
        📦 รายการอุปกรณ์ทั้งหมด
      </h2>

      <div style={{
        display: 'grid',
        gridTemplateColumns: 'repeat(auto-fill, minmax(280px, 1fr))',
        gap: '24px'
      }}>
        {mockEquipments.map((equipment) => (
          <EquipmentCard 
            key={equipment.id} 
            equipment={equipment} 
            onBorrow={handleBorrow} 
          />
        ))}
      </div>

      <AuthModal 
        isOpen={isModalOpen} 
        onClose={() => setIsModalOpen(false)} 
      />
    </div>
  );
}
